import manifest from "./gallery.manifest.json";

/**
 * The built-in character gallery: ready-made, full-body, rigged characters that
 * ship with the app (public/models/characters). Generated by
 * scripts/build-character-gallery.mjs from openly licensed (CC0) source packs —
 * see docs/characters.md for sources and licences.
 *
 * Each entry: { id, name, file, thumbnail?, credit, license, rig, clips? }
 *   file        path under /public, served from our own origin (no third party)
 *   rig         "quaternius" — bone naming of the shared animation library
 *
 * Until the gallery is built, this list is empty and the studio says so
 * honestly rather than showing placeholders.
 */
export const GALLERY_MODELS = Object.freeze(manifest.characters.map((entry) => Object.freeze(entry)));

/**
 * Shared animation clips (one file, many characters): clips bind by bone name,
 * so every character on the same rig reuses them. `map` turns our animation
 * states/emotes into the library's clip names.
 */
export const ANIMATION_LIBRARIES = Object.freeze(manifest.animations);

export function getGalleryModel(id) {
  return GALLERY_MODELS.find((model) => model.id === id) ?? null;
}

/** Client model descriptor for a gallery character (stable cache key, same-origin URL). */
export function galleryModelDescriptor(id) {
  const model = getGalleryModel(id);
  if (!model) return null;
  return { key: `library:${model.id}`, url: model.file, rig: model.rig };
}
